253	/// The kernel issues the attempt ID and the receive locator. A kernel that replaced the peer
254	/// (a disruptive change) is learned once, as for staging.
255	fn begin_attempt<P: Port>(
256	&mut self,
257	i: usize,
258	port: &mut P,
259	given: Option<&[u8; ATTEMPT_ID_LEN]>,
260	) -> Result<([u8; ATTEMPT_ID_LEN], u64), PortError> {
261	let slot = self.peers[i].slot;
262	let mut r = port.begin_attempt(slot, &self.peers[i].kernel_incarnation, given);
263	if matches!(&r, Err(e) if e.errno == Some(116)) {
264	let inc = port.kernel_incarnation(slot)?;
265	self.peers[i].kernel_incarnation = inc;
266	r = port.begin_attempt(slot, &inc, given);
267	}
268	r
269	}
