271	/// Time-driven work: start attempts, retransmit INIT, expire attempts, re-establish.
272	pub fn tick<P: Port>(&mut self, port: &mut P, now: Instant) {
273	for i in 0..self.peers.len() {
274	if self.peers[i].role != Role::Initiator {
275	continue;
276	}
277	enum Action {
278	None,
279	Start,
280	StartGranted,
281	GrantTimeout,
282	Retransmit,
283	Expire,
284	}
285	let action = match &self.peers[i].state {
286	State::Idle { not_before } if now >= *not_before => Action::Start,
287	State::Idle { .. } => Action::None,
288	State::AwaitGrant(a) if now.duration_since(a.started) >= GRANT_WAIT => {
289	Action::GrantTimeout
290	}
291	State::AwaitGrant(_) => Action::None,
292	State::Pending(p) if now.duration_since(p.started) >= ATTEMPT_DEADLINE => {
293	Action::Expire
294	}
295	State::Pending(p) if now >= p.next_retry => Action::Retransmit,
296	State::Pending(_) => Action::None,
297	State::Established { since }
298	if self.peers[i].rekey_requested
299	|| now.duration_since(*since) >= self.rekey_after =>
300	{
301	Action::StartGranted
302	}
303	State::Established { .. } => Action::None,
304	};
305	match action {
306	Action::None => {}
307	Action::Start => self.start_attempt(i, port, now, false),
308	Action::StartGranted => self.start_attempt(i, port, now, true),
309	Action::GrantTimeout => {
310	// No continuity grant in time: keep no flows, but do re-key.
311	let name = self.peers[i].name.clone();
312	self.say(format!(
313	"no continuity grant from {name}; making a fresh attempt instead"
314	));
315	self.start_attempt(i, port, now, false);
316	}
317	Action::Retransmit => self.retransmit(i, port, now),
318	Action::Expire => {
319	self.counts.attempts_failed += 1;
320	let f = self.peers[i].failures;
321	self.peers[i].failures += 1;
322	let wait = BACKOFF[f.min(BACKOFF.len() - 1)];
323	let name = self.peers[i].name.clone();
324	self.say(format!(
325	"attempt to {name} timed out; retrying in {}s",
326	wait.as_secs()
327	));
328	self.peers[i].state = State::Idle {
329	not_before: now + wait,
330	};
331	}
332	}
333	}
334	}
