336	/// Ask every established initiator peer for a new exchange now (key usage reached a limit).
337	/// Responders cannot start one. Returns how many peers will start.
338	pub fn request_rekey(&mut self) -> usize {
339	let mut n = 0;
340	for p in &mut self.peers {
341	if p.role == Role::Initiator && matches!(p.state, State::Established { .. }) {
342	p.rekey_requested = true;
343	n += 1;
344	}
345	}
346	n
347	}
