363	/// The responder granted continuity for the attempt this initiator asked about: the mode 1
364	/// INIT goes out now, naming the session being continued as its parent.
365	pub fn on_rekey_granted<P: Port>(
366	&mut self,
367	port: &mut P,
368	slot: u8,
369	attempt: [u8; ATTEMPT_ID_LEN],
370	now: Instant,
371	) {
372	let Some(i) = self.peers.iter().position(|p| p.slot == slot) else {
373	return;
374	};
375	let State::AwaitGrant(a) = &self.peers[i].state else {
376	return; // Late or repeated: nothing is waiting for it.
377	};
378	if a.attempt_id != attempt {
379	return;
380	}
381	let (attempt_id, initiator_locator, parent) = (a.attempt_id, a.initiator_locator, a.parent);
382	self.send_init(
383	i,
384	port,
385	now,
386	Mode::Rekey,
387	attempt_id,
388	initiator_locator,
389	parent,
390	);
391	}
