393	/// Adopt a configuration the kernel has just committed as a later revision.
394	///
395	/// `kernel_incarnations` is the kernel's STATUS after that commit. The kernel keeps a
396	/// peer's session across a commit only when nothing about the peer changed (role,
397	/// path MTU, endpoint, key, prefixes), so a slot whose incarnation is unchanged keeps
398	/// its exchange state and its running timers. Every other slot gets a fresh peer here
399	/// and a new exchange: the controller does not repeat the kernel's classification, it
400	/// follows the incarnation. A removed peer's state, including its cached RESPONSE, is
401	/// dropped.
402	pub fn reconfigure(
403	&mut self,
404	config: &GatewayConfig,
405	kernel_incarnations: &[(u8, [u8; INCARNATION_LEN])],
406	now: Instant,
407	) -> Reconfigured {
408	let mut old = std::mem::take(&mut self.peers);
409	let mut out = Reconfigured::default();
410	for p in &config.peers {
411	let kernel = kernel_incarnations
412	.iter()
413	.find(|(s, _)| *s == p.slot)
414	.map_or([0; INCARNATION_LEN], |(_, i)| *i);
415	let previous = old
416	.iter()
417	.position(|o| o.slot == p.slot)
418	.map(|at| old.swap_remove(at));
419	match previous {
420	// The same kernel peer, and the controller's own view still matches it.
421	Some(mut o)
422	if !is_zero(&kernel)
423	&& o.kernel_incarnation == kernel
424	&& o.public == p.public_key
425	&& o.role == p.role
426	&& o.path_budget == p.path_mtu =>
427	{
428	o.name.clone_from(&p.name);
429	self.peers.push(o);
430	out.kept.push(p.slot);
431	}
432	other => {
433	if other.is_some() {
434	out.replaced.push(p.slot);
435	} else {
436	out.added.push(p.slot);
437	}
438	self.peers.push(PeerCtl {
439	name: p.name.clone(),
440	slot: p.slot,
441	public: p.public_key,
442	role: p.role,
443	path_budget: p.path_mtu,
444	kernel_incarnation: kernel,
445	state: State::Idle { not_before: now },
446	failures: 0,
447	cached: None,
448	rekey_requested: false,
449	session_hash: None,
450	});
451	}
452	}
453	}
454	out.removed = old.iter().map(|o| o.slot).collect();
455	out.removed.sort_unstable();
456	self.peers.sort_by_key(|p| p.slot);
457	out
458	}
