460	/// Begin an attempt. With `granted` (the session is established) the re-key keeps the flows: the
461	/// kernel is asked for a continuity grant first and the mode 1 INIT follows its REKEY_GRANTED.
462	/// Without it, or when no grant can be asked for, the attempt is fresh (mode 0).
463	fn start_attempt<P: Port>(&mut self, i: usize, port: &mut P, now: Instant, granted: bool) {
464	self.peers[i].rekey_requested = false;
465	let (attempt_id, initiator_locator) = match self.begin_attempt(i, port, None) {
466	Ok(x) => x,
467	Err(e) => {
468	self.fail_start(i, now, format!("cannot begin an attempt: {e}"));
469	return;
470	}
471	};
472	if granted && let Some(parent) = self.peers[i].session_hash {
473	let slot = self.peers[i].slot;
474	match port.rekey_request(slot, &self.peers[i].kernel_incarnation, &attempt_id) {
475	Ok(()) => {
476	self.peers[i].state = State::AwaitGrant(Box::new(Awaiting {
477	attempt_id,
478	initiator_locator,
479	parent,
480	started: now,
481	}));
482	return;
483	}
484	Err(e) => {
485	// The kernel cannot grant (the session is closed or limits are hard): fresh.
486	let name = self.peers[i].name.clone();
487	self.say(format!(
488	"cannot ask {name} for a continuity grant ({e}); making a fresh attempt"
489	));
490	}
491	}
492	}
493	self.send_init(
494	i,
495	port,
496	now,
497	Mode::Fresh,
498	attempt_id,
499	initiator_locator,
500	[0; HASH_LEN],
501	);
502	}
