504	#[allow(clippy::too_many_arguments)]
505	fn send_init<P: Port>(
506	&mut self,
507	i: usize,
508	port: &mut P,
509	now: Instant,
510	mode: Mode,
511	attempt_id: [u8; ATTEMPT_ID_LEN],
512	initiator_locator: u64,
513	parent: [u8; HASH_LEN],
514	) {
515	let payload = HandshakePayload {
516	mode,
517	attempt_id,
518	incarnation: self.incarnation,
519	initiator_locator,
520	responder_locator: 0,
521	parent,
522	path_budget: self.peers[i].path_budget,
523	};
524	let initiator = match Initiator::start(&self.key, &self.peers[i].public, payload) {
525	Ok(x) => x,
526	Err(e) => {
527	self.fail_start(i, now, format!("cannot build INIT: {e}"));
528	return;
529	}
530	};
531	let slot = self.peers[i].slot;
532	if let Err(e) = port.exchange_tx(slot, initiator.init_bytes()) {
533	self.fail_start(i, now, format!("cannot send INIT: {e}"));
534	return;
535	}
536	self.counts.attempts_started += 1;
537	let name = self.peers[i].name.clone();
538	let kind = if mode == Mode::Rekey {
539	"granted re-key INIT"
540	} else {
541	"INIT"
542	};
543	self.say(format!("sent {kind} to {name}"));
544	self.peers[i].state = State::Pending(Box::new(Pending {
545	initiator,
546	started: now,
547	next_retry: now + RETRANSMIT[0],
548	retries: 0,
549	}));
550	}
