552	fn fail_start(&mut self, i: usize, now: Instant, why: String) {
553	self.counts.attempts_failed += 1;
554	let f = self.peers[i].failures;
555	self.peers[i].failures += 1;
556	self.say(why);
557	self.peers[i].state = State::Idle {
558	not_before: now + BACKOFF[f.min(BACKOFF.len() - 1)],
