562	fn retransmit<P: Port>(&mut self, i: usize, port: &mut P, now: Instant) {
563	let slot = self.peers[i].slot;
564	let State::Pending(p) = &mut self.peers[i].state else {
565	return;
566	};
567	// The exact same INIT bytes are resent (TECHNICAL_DESIGN.md 5.3).
568	let result = port.exchange_tx(slot, p.initiator.init_bytes());
569	p.retries += 1;
570	let step = RETRANSMIT[p.retries.min(RETRANSMIT.len() - 1)];
571	p.next_retry = now + step;
572	if let Err(e) = result {
573	let msg = format!("INIT retransmit failed: {e}");
574	self.say(msg);
575	}
576	}
