578	/// An INIT or RESPONSE the kernel forwarded. The kernel verified nothing but the
579	/// outer source; everything cryptographic is checked here.
580	pub fn on_exchange<P: Port>(&mut self, port: &mut P, ev: ExchangeRx, now: Instant) {
581	let Some(i) = self.peers.iter().position(|p| p.slot == ev.slot) else {
582	self.counts.rejected += 1;
583	return;
584	};
585	self.peers[i].kernel_incarnation = ev.kernel_incarnation;
586	match ev.bytes.get(4).copied() {
587	Some(1) => self.on_init(i, port, &ev.bytes, now),
588	Some(2) => self.on_response(i, port, &ev.bytes, now),
589	_ => self.counts.rejected += 1,
590	}
591	}
