593	fn stage_keys<P: Port>(
594	&mut self,
595	i: usize,
596	port: &mut P,
597	keys: &SessionKeys,
598	) -> Result<(), PortError> {
599	let slot = self.peers[i].slot;
600	let mut r = port.stage(slot, &self.peers[i].kernel_incarnation, keys);
601	// The kernel replaced the peer (a disruptive change): learn the new identity once.
602	if matches!(&r, Err(e) if e.errno == Some(116)) {
603	let inc = port.kernel_incarnation(slot)?;
604	self.peers[i].kernel_incarnation = inc;
605	r = port.stage(slot, &inc, keys);
606	}
607	r
608	}
