610	fn on_init<P: Port>(&mut self, i: usize, port: &mut P, init: &[u8], now: Instant) {
611	let name = self.peers[i].name.clone();
612	if self.peers[i].role != Role::Responder {
613	self.counts.rejected += 1;
614	self.say(format!("ignored INIT from {name}: we are its initiator"));
615	return;
616	}
617	let slot = self.peers[i].slot;
618	// A byte-identical duplicate gets the identical cached RESPONSE, nothing else.
619	if let Some(c) = &self.peers[i].cached
620	&& now.duration_since(c.at) < CACHE_LIFETIME
621	&& let Some(resp) = c.cache.replay_for(init)
622	{
623	let resp = resp.to_vec();
624	self.counts.duplicates_answered += 1;
625	if let Err(e) = port.exchange_tx(slot, &resp) {
626	self.say(format!("cannot resend RESPONSE: {e}"));
627	}
628	return;
629	}
630	// The kernel issues the responder's locator, for the attempt of the INIT it delivered.
631	let attempt = match parse_handshake(init) {
632	Ok(d) => d.attempt_id,
633	Err(e) => {
634	self.counts.rejected += 1;
635	self.say(format!("rejected INIT from {name}: {e}"));
636	return;
637	}
638	};
639	let responder_locator = match self.begin_attempt(i, port, Some(&attempt)) {
640	Ok((_, locator)) => locator,
641	Err(e) => {
642	self.counts.rejected += 1;
643	self.say(format!("cannot begin an attempt for {name}'s INIT: {e}"));
644	return;
645	}
646	};
647	let params = ResponderParams {
648	incarnation: self.incarnation,
649	responder_locator,
650	path_budget: self.peers[i].path_budget,
651	continuity_grant: self.peers[i].session_hash,
652	};
653	let public = self.peers[i].public;
654	let responded = match respond(&self.key, &public, init, &params) {
655	Ok(r) => r,
656	Err(e) => {
657	self.counts.rejected += 1;
658	self.say(format!("rejected INIT from {name}: {e}"));
659	return;
660	}
661	};
662	// Install the keys before the RESPONSE leaves, so the initiator's first record
663	// can already be opened; a failure to stage abandons the attempt.
664	if let Err(e) = self.stage_keys(i, port, &responded.keys) {
665	self.say(format!("cannot install keys for {name}: {e}"));
666	return;
667	}
668	if let Err(e) = port.exchange_tx(slot, &responded.response) {
669	self.say(format!("cannot send RESPONSE to {name}: {e}"));
670	}
671	self.peers[i].cached = Some(Cached {
672	cache: ResponseCache::new(init, &responded.response),
673	at: now,
674	});
675	self.peers[i].state = State::Established { since: now };
676	self.peers[i].session_hash = Some(responded.keys.handshake_hash);
677	self.peers[i].failures = 0;
678	self.counts.established += 1;
679	self.say(format!("tunnel to {name} established (responder)"));
680	}
681
682	fn on_response<P: Port>(&mut self, i: usize, port: &mut P, response: &[u8], now: Instant) {
683	let name = self.peers[i].name.clone();
684	let State::Pending(p) = &mut self.peers[i].state else {
685	// Not waiting for a RESPONSE (late duplicate, or never asked): drop it.
686	self.counts.rejected += 1;
687	return;
688	};
689	// A forged or stale RESPONSE leaves the attempt pending (Initiator::finish).
690	let keys = match p.initiator.finish(response) {
691	Ok(k) => k,
692	Err(e) => {
693	self.counts.rejected += 1;
694	let note = match e {
695	ExchangeError::Completed => "late".to_owned(),
