		memcpy(peer->rk_parent, parent, sizeof(parent));
		peer->rk_deadline_ns = now + VPT1_ATTEMPT_NS;
	} else {
		peer->grant_valid = true;
		peer->grant_used = false;
		memcpy(peer->grant_att, att, sizeof(att));
