/* cfg_lock held. */
static bool attempt_rx_in_use(struct vpt1_gw *gw, u64 rx)
{
	unsigned int i;

	for (i = 1; i <= VPT1_MAX_PEERS; i++) {
		struct vpt1_peer *p = peer_locked(gw, i);

		if (p && (locator_in_use(p, rx) || (p->att_valid && p->att_rx == rx)))
			return true;
	}
	return false;
