310 /// Read the configuration file once, bounded, so the bytes that were validated are the
311 /// bytes the watcher compares against later.
312 fn read_config(path: &Path) -> Result<Vec<u8>, ConfigError> {
313 let io_err = |source| ConfigError::Io {
314 path: path.display().to_string(),
315 source,
316 };
317 let mut bytes = Vec::new();
318 File::open(path)
319 .map_err(io_err)?
320 .take(MAX_CONFIG_BYTES + 1)
321 .read_to_end(&mut bytes)
322 .map_err(io_err)?;
323 if bytes.len() as u64 > MAX_CONFIG_BYTES {
324 return Err(ConfigError::TooLarge);
325 }
326 Ok(bytes)
327 }
