335 /// Notices a changed configuration file. It compares the bytes, not a timestamp, so an
336 /// editor's write-then-rename and a file replaced with identical content both behave. A
337 /// version that failed permanently is not retried (or logged again) until the file changes
338 /// once more. A version that failed transiently is retried after a delay, a bounded number
339 /// of times, then treated as rejected; a changed file resets that state.
340 pub struct Watcher {
341 path: PathBuf,
342 applied: Vec<u8>,
343 rejected: Option<Vec<u8>>,
344 retry: Option<Pending>,
345 }
346
347 /// A file version waiting for a transient refusal to clear.
348 struct Pending {
349 version: Vec<u8>,
350 /// Attempts made so far, the first one included.
351 attempts: u32,
352 next_at: Instant,
353 }
354
355 /// What `Watcher::retry_later` decided.
356 #[derive(Debug, PartialEq, Eq)]
357 pub enum Retry {
358 /// The same version will be offered again after the delay; `attempt` was the one that failed.
359 Later { attempt: u32 },
360 /// The attempts are used up; the version is now rejected.
361 GaveUp,
362 }
363
364 impl Watcher {
365 pub fn new(path: &Path, applied: Vec<u8>) -> Self {
366 Self {
367 path: path.to_owned(),
368 applied,
369 rejected: None,
370 retry: None,
371 }
372 }
373
374 /// The new content if the file now differs from what is running and from the last
375 /// rejected version, and, for a version waiting out a transient refusal, only once its
376 /// retry time has come. An unreadable file (mid-replace) is simply tried again next time.
377 pub fn poll(&mut self, now: Instant) -> Option<Vec<u8>> {
378 let bytes = match read_config(&self.path) {
379 Ok(b) => b,
380 // Too large is a change worth reporting; the parse step rejects it by size.
381 Err(ConfigError::TooLarge) => vec![0; usize::try_from(MAX_CONFIG_BYTES).ok()? + 1],
382 Err(_) => return None,
383 };
384 // A file that is no longer the version being retried resets the retry state.
385 if self.retry.as_ref().is_some_and(|p| p.version != bytes) {
386 self.retry = None;
387 }
388 if bytes == self.applied || self.rejected.as_deref() == Some(bytes.as_slice()) {
389 return None;
390 }
391 if self.retry.as_ref().is_some_and(|p| now < p.next_at) {
392 return None;
393 }
394 Some(bytes)
395 }
396
397 pub fn applied(&mut self, bytes: Vec<u8>) {
398 self.applied = bytes;
399 self.rejected = None;
400 self.retry = None;
401 }
402
403 pub fn rejected(&mut self, bytes: Vec<u8>) {
404 self.rejected = Some(bytes);
405 self.retry = None;
406 }
407
408 /// The kernel refused `bytes` transiently at `now`: schedule another attempt, or give
409 /// up (reject the version) once `RELOAD_MAX_ATTEMPTS` have been made.
410 pub fn retry_later(&mut self, bytes: Vec<u8>, now: Instant) -> Retry {
411 let attempts = match self.retry.take() {
412 Some(p) if p.version == bytes => p.attempts + 1,
413 _ => 1,
414 };
415 if attempts >= RELOAD_MAX_ATTEMPTS {
416 self.rejected(bytes);
417 return Retry::GaveUp;
418 }
419 self.retry = Some(Pending {
420 version: bytes,

				A(REQUEST_ID), op_validate },
	[VPT1_CMD_COMMIT_CONFIG] = { OWNER | A(CONFIG_REVISION), A(REQUEST_ID),
				     op_commit },
	[VPT1_CMD_STAGE_GENERATION] = { OWNER | A(PEER_SLOT) | A(PEER_INCARNATION) |
					A(ATTEMPT_ID) | A(HANDSHAKE_HASH) |
					A(LOCAL_RX) | A(REMOTE_RX) | A(TX_KEY) |
