957 /// Deliver everything in flight, in order, until nothing moves.
958 fn pump(&mut self) {
959 loop {
960 let (to_a, to_b, grants) = {
961 let mut w = self.wire.lock().unwrap();
962 (
963 std::mem::take(&mut w.to_a),
964 std::mem::take(&mut w.to_b),
965 std::mem::take(&mut w.grants_to_a),
966 )
967 };
968 if to_a.is_empty() && to_b.is_empty() && grants.is_empty() {
969 return;
970 }
971 for (slot, attempt) in grants {
972 self.a
973 .on_rekey_granted(&mut self.pa, slot, attempt, self.now);
974 }
975 for m in to_b {
976 let ev = ExchangeRx {
977 slot: 1,
978 kernel_incarnation: [0xB1; 16],
979 bytes: m,
980 };
981 self.b.on_exchange(&mut self.pb, ev, self.now);
982 }
983 for m in to_a {
984 let ev = ExchangeRx {
985 slot: 1,
986 kernel_incarnation: [0xA1; 16],
987 bytes: m,
988 };
989 self.a.on_exchange(&mut self.pa, ev, self.now);
990 }
991 }
992 }
